// Save as reproduce-tti-bug.js
// Usage: node reproduce-tti-bug.js
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

async function runLighthouse() {
  // 1) Launch a headless Chrome.
  const chrome = await chromeLauncher.launch({chromeFlags: ['--headless']});
  const options = {
    port: chrome.port,
    throttlingMethod: 'provided',  // use the DevTools/provided path
    onlyCategories: ['performance'],
    logLevel: 'info',
  };

  // 2) Point at the glitch page that delays its FCP by 1700 ms
  const url = 'https://persistent-friendly-authority.glitch.me/?delayFcpMs=1700';

  // 3) Run Lighthouse
  const { lhr } = await lighthouse(url, options);

  // 4) Inspect the TTI and TBT audits
  console.log('Performance score:', lhr.categories.performance.score);
  console.log('First Contentful Paint:', lhr.audits['first-contentful-paint'].displayValue);
  console.log('Time to Interactive:', lhr.audits.interactive.errorMessage || lhr.audits.interactive.displayValue);
  console.log('Total Blocking Time:', lhr.audits['total-blocking-time'].errorMessage || lhr.audits['total-blocking-time'].displayValue);

  await chrome.kill();
}

runLighthouse().catch(err => {
  console.error(err);
  process.exit(1);
});
